<?php
namespace qqworld_collector\module\collect_filter; class download_to_local extends filter { var $mime_types; public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if ($mode != 'test') { $url = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $item, $source_link); $save_to = $args == 'local' ? 'local' : 'lib'; if ($args == 'local' && !defined( 'ALLOW_UNFILTERED_UPLOADS' )) define( 'ALLOW_UNFILTERED_UPLOADS' , true); if ($args != 'manual-download') { $GLOBALS['QC']->auto_save_attachment->save_attachment->download_args = $download_args; $attachment = $GLOBALS['QC']->auto_save_attachment->save_attachment->grab_attachment_url($url, null, $save_to); } switch ($args) { case 'local': if ( strstr($attachment['type'], 'image') !== false ) { if ( isset($attachment['sizes']) && isset($attachment['sizes']['full']) ) { $item = $attachment['sizes']['full']['url']; } } else { if ( isset($attachment['file_src']) ) { $item = $attachment['file_src']; } } break; case 'media-library': case 'media-library-id': if (isset($attachment['attachment_id'])) $item = $attachment['attachment_id']; break; case 'media-library-url': if (isset($attachment['attachment_id'])) $item = wp_get_attachment_url($attachment['attachment_id']); break; case 'manual-download': $y = date('Y'); $m = date('m'); $d = date('d'); $domain = $this->options->qc_download_to_local_path_domain ? $this->options->qc_download_to_local_path_domain : home_url(); $path = $this->options->qc_download_to_local_path_path ? $this->options->qc_download_to_local_path_path : '/wp-content/uploads/download/'; $url = str_replace('\\', '/', $domain . $path . $y . '/' . $m . '/' . $d . '/' . basename($item)); require_once ( ABSPATH . 'wp-admin/includes/class-wp-filesystem-base.php' ); require_once ( ABSPATH . 'wp-admin/includes/class-wp-filesystem-direct.php' ); $fileSystemDirect = new \WP_Filesystem_Direct(false); $path = preg_replace(array('/^[\/\\\]/i', '/[\/\\\]$/i'), '', $path) . DIRECTORY_SEPARATOR . $y . DIRECTORY_SEPARATOR . $m . DIRECTORY_SEPARATOR . $d . DIRECTORY_SEPARATOR; $paths = array_filter(preg_split('/[\/\\\]/', $path)); $path = ABSPATH; foreach ($paths as $p) { $path .= $p . DIRECTORY_SEPARATOR; if (!is_dir($path)) $fileSystemDirect->mkdir($path); } $path .= 'url.txt'; $content = file_exists($path) ? file_get_contents($path) : ''; if (!empty($content)) { $content = explode("\n", str_replace("\xEF\xBB\xBF", '', $content)); $content[] = $item; $content = array_flip(array_flip($content)); $content = implode("\n", array_filter($content)); } else { $content = $item; } file_put_contents($path, "\xEF\xBB\xBF" . $content); $item = $url; break; } } return $item; } } ?>